 const parsed=new Date(String(date)+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date))||!Number.isFinite(parsed.getTime())||parsed.toISOString().slice(0,10)!==date||!['1','2','3'].includes(session))throw Error('Ngày hoặc buổi điểm danh không hợp lệ.');
