   for(const q of questions.filter(q=>q.type==='essay'||a.gradingMode==='manual')){const prev=old.details.find(t=>t.qid===q.id),row=scored.details.find(t=>t.qid===q.id);if(prev?.points!==null&&prev?.points!==undefined){row.points=prev.points;row.comment=prev.comment||'';}}
